package vn.iotstar.service.impl; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import vn.iotstar.dto.UserDTO; import vn.iotstar.entity.*; import vn.iotstar.mapper.UserMapper; import vn.iotstar.repository.*; import vn.iotstar.service.UserService; @Service @RequiredArgsConstructor public class UserServiceImpl implements UserService{private final UserRepository repo;private final RoleRepository roles;private final UserMapper mapper;private final PasswordEncoder encoder; public Page<UserDTO> findAll(String k,int p,int s){Pageable pg=PageRequest.of(Math.max(p,0),Math.max(s,1),Sort.by(Sort.Direction.DESC,"id"));return repo.search(k==null?"":k,pg).map(u->{UserDTO d=mapper.toDTO(u);d.setProductCount(repo.countProductsByUserId(u.getId()));return d;});} public UserDTO findById(Long id){User u=repo.findById(id).orElseThrow(()->new IllegalArgumentException("User không tồn tại"));UserDTO d=mapper.toDTO(u);d.setProductCount(repo.countProductsByUserId(id));return d;} @Transactional public UserDTO create(UserDTO d){if(repo.existsByUsername(d.getUsername()))throw new IllegalArgumentException("Username đã tồn tại");if(repo.existsByEmail(d.getEmail()))throw new IllegalArgumentException("Email đã tồn tại");User u=mapper.toEntity(d);Role r=roles.findByName(d.getRoleName()==null||d.getRoleName().isBlank()?"ROLE_USER":d.getRoleName()).orElseThrow(()->new IllegalArgumentException("Role không tồn tại"));u.setRole(r);u.setPassword(encoder.encode("123456"));u.setEnabled(d.isEnabled());return mapper.toDTO(repo.save(u));} @Transactional public UserDTO update(Long id,UserDTO d){User u=repo.findById(id).orElseThrow(()->new IllegalArgumentException("User không tồn tại"));u.setUsername(d.getUsername());u.setEmail(d.getEmail());u.setFullName(d.getFullName());u.setEnabled(d.isEnabled());if(d.getRoleName()!=null&&!d.getRoleName().isBlank())u.setRole(roles.findByName(d.getRoleName()).orElseThrow(()->new IllegalArgumentException("Role không tồn tại")));return mapper.toDTO(repo.save(u));} public void delete(Long id){repo.deleteById(id);} public long countUsers(){return repo.count();} public long countProducts(Long id){return repo.countProductsByUserId(id);}}